text(await tools.exec_command({cmd:`cat > tmp/req-016/check-startup-metric.mjs <<'EOF'
import assert from "node:assert/strict";
import { spawn } from "node:child_process";
import { once } from "node:events";
import { mkdtemp, readFile } from "node:fs/promises";
import { createServer } from "node:net";
import { resolve } from "node:path";
import { setTimeout as delay } from "node:timers/promises";

async function port() {
  const server = createServer().listen(0, "127.0.0.1");
  await once(server, "listening");
  const value = server.address().port;
  await new Promise((done) => server.close(done));
  return value;
}

const fixture = await mkdtemp(resolve("tmp/req-016/startup-metric-"));
const driverPort = await port();
const discoveryPort = await port();
const app = spawn("target/release/examples/native-contact-eval", [
  resolve(fixture, "app"), String(driverPort), String(discoveryPort),
], { stdio: "ignore" });
const exited = once(app, "exit");
try {
  let ready = false;
  for (let attempt = 0; attempt < 120 && app.exitCode === null; attempt++) {
    try {
      const response = await fetch(\`http://127.0.0.1:\${driverPort}/status\`, { signal: AbortSignal.timeout(500) });
      ready = Boolean((await response.json()).value?.ready);
    } catch { /* The embedded server has not bound its local port yet. */ }
    if (ready) break;
    await delay(100);
  }
  assert.ok(ready, "fixture desktop startup did not reach WebDriver ready");
  const log = resolve(fixture, "app/logs/mesh-talk.log");
  let records = [];
  for (let attempt = 0; attempt < 25; attempt++) {
    const current = await readFile(log, "utf8").catch(error => {
      if (error.code === "ENOENT") return "";
      throw error;
    });
    records = current.match(/desktop_host_ready_ms=\\d+/gu) ?? [];
    if (records.length) break;
    await delay(100);
  }
  assert.equal(app.exitCode, null, "startup metric must be recorded with desktop running");
  assert.equal(records.length, 1, "expected one startup metric while desktop is running");
  console.log(records[0]);
} finally {
  if (app.exitCode === null && app.signalCode === null) app.kill("SIGTERM");
  await exited;
}
EOF
